create table if not exists public.media_categories (id bigint generated by default as identity primary key,name text not null unique,slug text not null unique,description text,created_at timestamptz not null default now());
create table if not exists public.media_authors (id bigint generated by default as identity primary key,name text not null,slug text not null unique,bio text,avatar_url text,created_at timestamptz not null default now());
create table if not exists public.media_articles (id bigint generated by default as identity primary key,title text not null,slug text not null unique,excerpt text,content text not null default '',category_id bigint references public.media_categories(id) on delete set null,author_id bigint references public.media_authors(id) on delete set null,featured_image text,status text not null default 'draft' check(status in ('draft','review','published','archived')),article_type text not null default 'article' check(article_type in ('article','news','analysis','guide','opinion')),seo_title text,meta_description text,published_at timestamptz,updated_at timestamptz not null default now(),created_at timestamptz not null default now());
create table if not exists public.media_tags (id bigint generated by default as identity primary key,name text not null unique,slug text not null unique,created_at timestamptz not null default now());
create table if not exists public.media_article_tags (article_id bigint not null references public.media_articles(id) on delete cascade,tag_id bigint not null references public.media_tags(id) on delete cascade,primary key(article_id,tag_id));
create table if not exists public.media_sources (id bigint generated by default as identity primary key,article_id bigint not null references public.media_articles(id) on delete cascade,title text,url text not null,publisher text,published_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.media_topics (id bigint generated by default as identity primary key,topic text not null,category_id bigint references public.media_categories(id) on delete set null,priority integer not null default 0,status text not null default 'queued' check(status in ('queued','processing','published','skipped','failed')),used_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.media_autopilot (id integer primary key default 1,enabled boolean not null default false,mode text not null default 'review' check(mode in ('review','full_auto')),publishing_frequency text not null default 'daily' check(publishing_frequency in ('manual','daily','twice_daily','weekly')),last_run_at timestamptz,next_run_at timestamptz,updated_at timestamptz not null default now(),constraint media_autopilot_single_row check(id=1));
create table if not exists public.media_automation_logs (id bigint generated by default as identity primary key,action text not null,status text not null,article_id bigint references public.media_articles(id) on delete set null,topic_id bigint references public.media_topics(id) on delete set null,message text,created_at timestamptz not null default now());
create index if not exists idx_media_articles_status on public.media_articles(status);
create index if not exists idx_media_articles_category on public.media_articles(category_id);
create index if not exists idx_media_articles_published on public.media_articles(published_at desc);
create index if not exists idx_media_topics_status on public.media_topics(status);
create index if not exists idx_media_sources_article on public.media_sources(article_id);
insert into public.media_categories(name,slug,description) values ('News','news','Current news and important developments.'),('AI','ai','Artificial intelligence, tools, research and trends.'),('Promotion','promotion','Digital promotion, creators, marketing and online growth.'),('Crypto','crypto','Cryptocurrency, blockchain, Web3 and related developments.'),('Money','money','Personal finance, fintech, business and money education.') on conflict(slug) do nothing;
