insert into public.media_autopilot(id,enabled,mode,publishing_frequency) values(1,false,'review','daily') on conflict(id) do nothing;
alter table public.media_categories enable row level security;
alter table public.media_authors enable row level security;
alter table public.media_articles enable row level security;
alter table public.media_tags enable row level security;
alter table public.media_article_tags enable row level security;
alter table public.media_sources enable row level security;
alter table public.media_topics enable row level security;
alter table public.media_autopilot enable row level security;
alter table public.media_automation_logs enable row level security;
drop policy if exists "Public can read published articles" on public.media_articles;
create policy "Public can read published articles" on public.media_articles for select to anon,authenticated using(status='published');
drop policy if exists "Public can read categories" on public.media_categories;
create policy "Public can read categories" on public.media_categories for select to anon,authenticated using(true);
drop policy if exists "Public can read authors" on public.media_authors;
create policy "Public can read authors" on public.media_authors for select to anon,authenticated using(true);
drop policy if exists "Public can read tags" on public.media_tags;
create policy "Public can read tags" on public.media_tags for select to anon,authenticated using(true);
drop policy if exists "Public can read article tags" on public.media_article_tags;
create policy "Public can read article tags" on public.media_article_tags for select to anon,authenticated using(true);
drop policy if exists "Public can read article sources" on public.media_sources;
create policy "Public can read article sources" on public.media_sources for select to anon,authenticated using(exists(select 1 from public.media_articles a where a.id=article_id and a.status='published'));
